public class Phoneme_toString_TriageGen1Test {

    @Test
    public void testToStringWithSinglePhoneme() {
        // Arrange
        CharSequence text = "abc";
        LanguageSet languages = LanguageSet.empty(); // Assuming empty exists or using a mock-like approach
        Phoneme phoneme = new Phoneme(text, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        assertEquals("abc[[]", result); 
        // Note: If LanguageSet.toString() returns something else, adjust expectation. 
        // Based on the code: phonemeText.toString() + "[" + languages + "]"
    }

    @Test
    public void testToStringWithComplexLanguageSet() {
        // Arrange
        CharSequence text = "xyz";
        // Creating a dummy language set via a hypothetical implementation 
        // since the internal structure of LanguageSet isn't provided, 
        // we assume it has a standard toString().
        LanguageSet languages = LanguageSet.empty(); 
        Phoneme phoneme = new Phoneme(text, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        String expected = "xyz[" + languages.toString() + "]";
        assertEquals(expected, result);
    }

    @Test
    public void testToStringWithJoinedPhonemes() {
        // Arrange
        LanguageSet languages = LanguageSet.empty();
        Phoneme p1 = new Phoneme("a", languages);
        Phoneme p2 = new Phoneme("b", languages);

        // The constructor Phoneme(Phoneme, Phoneme) likely aggregates text
        Phoneme joined = new Phoneme(p1, p2);

        // Act
        String result = joined.toString();

        // Assert
        // If join/constructor concatenates text: "ab[[]"
        // We test the path through the toString method specifically
        String expectedText = joined.getPhonemeText().toString();
        String expected = expectedText + "[" + joined.getLanguages() + "]";
        assertEquals(expected, result);
    }

    @Test
    public void testToStringWithThreeArgConstructor() {
        // Arrange
        CharSequence text = "test";
        LanguageSet languages = LanguageSet.empty();
        Phoneme p1 = new Phoneme("a", languages);
        Phoneme p2 = new Phoneme("b", languages);

        Phoneme phoneme = new Phoneme(p1, p2, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        String expectedText = phoneme.getPhonemeText().toString();
        String expected = expectedText + "[" + languages.toString() + "]";
        assertEquals(expected, result);
    }
}
